cd ~/measurement_env/hera/models/tetralayer_fs_count && menv python -c "
import sys; sys.path.insert(0,'.')
import numpy as np, fs_count_b0 as M
print('n[1e12]  F_L      ABAB light  heavy   sum   part_light  ratio h/l   m*_l  m*_h    ABCA F  m*')
for n12 in [1.0,1.2,1.5,1.8,2.1,2.4,2.7,3.0,3.3]:
    n=n12*1e12
    try:
        ef,orbs=M.abab_fs(n); ms=M.abab_mstar(n)
        Fs=[o[0] for o in orbs]; mm=[m[1] for m in ms]
        FL=abs(n)*1e4*6.62607015e-34/(4*1.602176634e-19)
        s=sum(Fs)
        if len(Fs)>=2:
            l,h=Fs[0],Fs[-1]
            print(f'{n12:5.2f} {FL:7.2f}   {l:7.2f} {h:7.2f} {s:7.2f}  {l/s:8.3f}  {h/l:8.3f}  {mm[0]:.4f} {mm[-1]:.4f}', end='')
        else:
            print(f'{n12:5.2f} {FL:7.2f}   {Fs} ', end='')
        try:
            fa,ma=M.abca_mstar(n); print(f'   {fa:7.2f} {ma:.3f}')
        except Exception as e: print('  abca:',e)
    except Exception as e:
        print(n12,'ERR',e)
" 2>&1 | tail -20

